import { ref, type Ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { ConversationTurn, Exploration } from '@/types'
import { sendAdvisingMessage } from '@/services/advisingApi'
import { updateExplorationDerived } from '@/services/explorationApi'
import {
  buildSelfAwarenessCard,
  isFinalReport,
  isFastAssessmentPrompt,
  parseStage2Reply,
  parseStage3Report
} from '@/services/advisingParser'
import { TOPICS } from '@/data/topics'

export interface SendOutcome {
  reply: string
  isFinal: boolean
}

/**
 * 驅動與 AdvisingChatService 的真實多輪對話：送出使用者這輪的回覆、串流累積 AI 回覆、
 * 依目前階段解析回覆內容並把衍生欄位（answers/summary/card/fast/status）PATCH 回後端。
 *
 * 對話紀錄本身（history）不在這裡送出或寫回——後端在 RunController.RunAdvisingExploreFlow
 * 收到 exploration_id 後會自己從資料表讀出歷史、呼叫 AI、串流結束後存回去。這裡仍然在本機
 * 維護一份 history 的鏡像（只用來算 historyLength，不會送給後端），因為修改上一題答案時
 * （見 useExploration.ts 的 truncateAfter）需要知道「這題結束當下後端的 history 長度」，
 * 才能請後端把 history 截回那個長度。
 */
export function useAdvisingConversation(exploration: Ref<Exploration | null>) {
  const { t } = useI18n()
  const sending = ref(false)
  const streamingText = ref('')
  const error = ref<string | null>(null)

  function topicLabelOf(current: Exploration): string {
    return current.topicCustomLabel ?? t(TOPICS.find(o => o.key === current.topic)?.labelKey ?? current.topic)
  }

  function historyOf(): ConversationTurn[] {
    return exploration.value?.history ?? []
  }

  async function persistDerived(current: Exploration, patch: Partial<Exploration>): Promise<void> {
    try {
      await updateExplorationDerived(current.id, {
        answers: patch.answers ?? current.answers,
        summary: patch.summary ?? current.summary,
        card: patch.card ?? current.card,
        fast: patch.fast ?? current.fast,
        status: patch.status ?? current.status
      })
    } catch (err) {
      // 對話本身已經成功（AI 回覆已經拿到、本機狀態已經更新），衍生欄位存檔失敗不應該擋住
      // 使用者繼續往下走；下一次任何欄位變動（含 useExploration.ts 的自動存檔）都會再送一次。
      console.error('[useAdvisingConversation] persist derived fields failed', err)
    }
  }

  /** 送出一輪使用者訊息，回傳這輪 AI 的完整回覆（已經套用過 Stage 2/3 解析並寫回 exploration）。 */
  async function send(userText: string): Promise<SendOutcome> {
    const current = exploration.value
    if (!current) throw new Error('exploration not loaded')

    sending.value = true
    streamingText.value = ''
    error.value = null

    try {
      const history = historyOf()
      const reply = await sendAdvisingMessage(current.id, userText, delta => {
        streamingText.value += delta
      })

      const nextHistory: ConversationTurn[] = [
        ...history,
        { role: 'user', text: userText },
        { role: 'model', text: reply }
      ]
      const patch: Partial<Exploration> = { history: nextHistory }
      let isFinal = false

      const stage2 = parseStage2Reply(reply)
      if (stage2) {
        const answers = [...current.answers]
        const idx = answers.findIndex(a => a.questionIndex === stage2.questionNumber - 1)
        const entry = {
          questionIndex: stage2.questionNumber - 1,
          text: answers[idx]?.text ?? '',
          updatedAt: new Date().toISOString(),
          reflection: stage2.reflection,
          question: stage2.question,
          rawReply: reply,
          historyLength: nextHistory.length
        }
        if (idx >= 0) answers[idx] = { ...answers[idx], ...entry }
        else answers.push(entry)
        patch.answers = answers
      } else if (isFinalReport(reply)) {
        isFinal = true
        const parsed = parseStage3Report(reply)
        const summary = parsed?.summary ?? [{ key: 'raw' as const, title: '總結報告', body: reply }]
        patch.summary = summary
        if (parsed?.fast && current.fast) {
          patch.fast = { ...current.fast, ...parsed.fast }
        }
        const topicLabel = topicLabelOf(current)
        patch.card = {
          topicLabel,
          date: new Date().toISOString().slice(0, 10),
          ...buildSelfAwarenessCard(topicLabel, summary)
        }
        patch.status = 'completed'
      } else if (!isFastAssessmentPrompt(reply) && (current.fast?.scores?.length ?? 0) > 0) {
        // 非預期格式（不是新一題、不是總結報告、也不是 FAST 自評提示）——多半是 Stage 2
        // 期間解析失敗，用原始文字頂著一個新題目卡位，至少不讓畫面開天窗。
        // 判斷「是否已進入 Stage 2」要用 fast.scores 是否存在，不能用 answers.length，
        // 否則 Stage 2 第一題（FAST 結束後緊接輸出的合併回覆）解析失敗時會被排除在保底機制外，
        // 畫面直接空白；且如果改成完全不判斷，Stage 1 開場白那輪也會被誤存成假的第一題。
        console.warn('[useAdvisingConversation] Stage 2 reply did not match expected format, using raw fallback', reply)
        const answers = [...current.answers]
        answers.push({
          questionIndex: answers.length,
          text: '',
          updatedAt: new Date().toISOString(),
          rawReply: reply,
          historyLength: nextHistory.length
        })
        patch.answers = answers
      }

      exploration.value = { ...current, ...patch, updatedAt: new Date().toISOString() }
      await persistDerived(current, patch)
      return { reply, isFinal }
    } catch (err) {
      error.value = err instanceof Error ? err.message : String(err)
      // 錯誤原因（後端回的 error 訊息、或 fetch/串流讀取本身的例外）留一份在 console，
      // 不然畫面只會顯示制式的「傳送失敗」，事後完全查不出當下實際發生什麼事。
      console.error('[useAdvisingConversation] send failed', err)
      throw err
    } finally {
      sending.value = false
    }
  }

  /**
   * 送出 Stage 1.5 的六題自評分數（後端期待的格式是 "4,5,3,2,4,3"）。
   * 分數本身先存起來；directionScore/resourceScore/quadrant/advice 等 Stage 3 報告解析出來才補上。
   */
  async function submitFastScores(scores: number[]): Promise<SendOutcome> {
    const current = exploration.value
    if (!current) throw new Error('exploration not loaded')
    const fast = { scores }
    exploration.value = { ...current, fast, updatedAt: new Date().toISOString() }
    await persistDerived(current, { fast })
    return send(scores.join(','))
  }

  return { sending, streamingText, error, send, submitFastScores }
}

import { inject, onUnmounted, provide, ref, watch, type InjectionKey, type Ref } from 'vue'
import type { Answer, Exploration, SelfAwarenessCard, SummarySection } from '@/types'
import { getExploration, truncateExploration, updateExplorationDerived } from '@/services/explorationApi'
import { useAutosave } from './useAutosave'

interface ExplorationContextValue {
  exploration: Ref<Exploration | null>
  loading: Ref<boolean>
  setAnswer: (questionIndex: number, text: string) => void
  truncateAfter: (questionIndex: number) => Promise<void>
  finish: (summary: SummarySection[], card: SelfAwarenessCard) => void
}

const ExplorationKey: InjectionKey<ExplorationContextValue> = Symbol('Exploration')

/**
 * 依 id（可為 route param 的 reactive ref）提供一份探索紀錄的讀寫狀態，answers/summary/card/fast/status
 * 這幾個衍生欄位會自動 debounce PATCH 回後端。history（AI 對話的權威狀態）不在這裡寫，
 * 由 RunController.RunAdvisingExploreFlow 在每輪對話結束後直接存回去（見 useAdvisingConversation.ts）。
 */
export function provideExploration(id: Ref<string>): ExplorationContextValue {
  const exploration = ref<Exploration | null>(null) as Ref<Exploration | null>
  const loading = ref(true)

  async function load(explorationId: string) {
    loading.value = true
    try {
      exploration.value = await getExploration(explorationId)
    } catch (err) {
      console.error('[useExploration] load failed', err)
      exploration.value = null
    } finally {
      loading.value = false
    }
  }

  void load(id.value)

  const { flush } = useAutosave(
    exploration,
    e => {
      if (!e) return
      updateExplorationDerived(e.id, {
        answers: e.answers,
        summary: e.summary,
        card: e.card,
        fast: e.fast,
        status: e.status
      }).catch(err => {
        console.error('[useExploration] autosave failed', err)
      })
    },
    300
  )

  // id 改變時（切換到不同探索，或同一路由帶不同 ?q）：先把舊紀錄的待寫入內容存檔，再載入新紀錄
  watch(id, (newId, oldId) => {
    if (oldId !== undefined) flush()
    void load(newId)
  })

  onUnmounted(flush)

  const setAnswer = (questionIndex: number, text: string) => {
    const prev = exploration.value
    if (!prev) return
    const now = new Date().toISOString()
    const answers: Answer[] = [...prev.answers]
    const idx = answers.findIndex(a => a.questionIndex === questionIndex)
    if (idx >= 0) answers[idx] = { ...answers[idx], text, updatedAt: now }
    else answers.push({ questionIndex, text, updatedAt: now })
    exploration.value = { ...prev, answers, updatedAt: now }
  }

  /**
   * 「修改上一題答案」：answers 在本機截掉，history 交給後端截（POST .../truncate）。
   * 兩邊都要截，否則下次送出時後端會從沒截過的 history 判斷題號，跟畫面顯示的題號對不上。
   */
  const truncateAfter = async (questionIndex: number) => {
    const prev = exploration.value
    if (!prev) return
    const keptAnswers = questionIndex < 0 ? [] : prev.answers.filter(a => a.questionIndex <= questionIndex)
    // 真實對話模式下，把 history 也截回這題結束當下的長度，才不會讓後端收到使用者已經捨棄的未來回合
    // （見 Answer.historyLength 的說明）；找不到記錄長度（例如解析失敗保底資料）就整包保留不動。
    const keptHistoryLength = questionIndex < 0 ? 0 : keptAnswers.at(-1)?.historyLength

    if (keptHistoryLength !== undefined) {
      await truncateExploration(prev.id, keptHistoryLength)
    }

    exploration.value = {
      ...prev,
      answers: keptAnswers,
      history: keptHistoryLength !== undefined ? prev.history?.slice(0, keptHistoryLength) : prev.history,
      summary: undefined,
      card: undefined,
      status: 'in-progress',
      updatedAt: new Date().toISOString()
    }
  }

  const finish = (summary: SummarySection[], card: SelfAwarenessCard) => {
    const prev = exploration.value
    if (!prev) return
    exploration.value = { ...prev, summary, card, status: 'completed', updatedAt: new Date().toISOString() }
  }

  const value: ExplorationContextValue = { exploration, loading, setAnswer, truncateAfter, finish }
  provide(ExplorationKey, value)
  return value
}

export function useExploration(): ExplorationContextValue {
  const ctx = inject(ExplorationKey)
  if (!ctx) throw new Error('useExploration must be used within a component tree that called provideExploration()')
  return ctx
}

