        private readonly IAdvisingChatService _advisingService;

        public ExplorationController(IChataiModule chataiModule, IAdvisingChatService advisingService)
        {
            _chataiModule = chataiModule;
            _advisingService = advisingService;
        }

        [HttpPost]
        public IActionResult Create([FromBody] CreateExplorationRequest request)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            if (string.IsNullOrWhiteSpace(request.Topic))
                return BadRequest("Missing topic.");

            var now = DateTime.Now;

            // 預先把「開場白這輪」寫進 history，讓 Critical Conversation State Rule 判定 Stage 1
            // 已經跑過，議題一送出（RunController.RunAdvisingExploreFlow）就直接進 Stage 1.5 自評，
            // 不會重複輸出開場白。這段開場白同時也是前端 TopicSelectPage 顯示的靜態文案
            // （見 _frontend/chatai/apps/explore/src/i18n/zh-TW.json 的 topics.opening）。
            var openingHistory = new List<(string Role, string Text)>
            {
                ("user", "start"),
                ("model", _advisingService.GetOpeningText())
            };

            var record = new Exploration
            {
                id = Guid.NewGuid(),
                account_name = userId,
                topic = request.Topic,
                topic_custom_label = request.TopicCustomLabel,
                status = "in-progress",
                history_json = ExplorationHistoryJson.Serialize(openingHistory),
                is_del = false,
                create_date = now,
                update_date = now,
            };

            if (!_chataiModule.AddExploration(record))
                return BadRequest("建立探索紀錄失敗。");

            return Ok(ToResponse(record));
        }

        [HttpGet]
        public IActionResult List()
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            var records = _chataiModule.GetExplorationListForAccount(userId);
            return Ok(records.Select(ToResponse));
        }

        [HttpGet("{id}")]
        public IActionResult GetById(Guid id)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            var record = _chataiModule.GetExplorationById(id);
            if (!IsOwnedBy(record, userId))
                return NotFound();

            return Ok(ToResponse(record!));
        }

        /// <summary>
        /// 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位，不動 history_json
        /// （history 只能透過 RunController.RunAdvisingExploreFlow 或 Truncate 變動）。
        /// </summary>
        [HttpPatch("{id}")]
        public IActionResult UpdateDerived(Guid id, [FromBody] UpdateExplorationDerivedRequest request)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            var record = _chataiModule.GetExplorationById(id);
            if (!IsOwnedBy(record, userId))
                return NotFound();

            var ok = _chataiModule.UpdateExplorationDerived(
                id,
                userId,
                request.Answers?.GetRawText(),
                request.Summary?.GetRawText(),
                request.Card?.GetRawText(),
                request.Fast?.GetRawText(),
                string.IsNullOrWhiteSpace(request.Status) ? record!.status : request.Status,
                DateTime.Now);

            if (!ok)
                return BadRequest("更新探索紀錄失敗。");

            return Ok();
        }

        [HttpDelete("{id}")]
        public IActionResult Delete(Guid id)
        {
            var userId = JWTHelper.GetAccountNameFromRequest(Request);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized("缺少或無效的使用者身份 (X-Access-Token).");

            var record = _chataiModule.GetExplorationById(id);
            if (!IsOwnedBy(record, userId))
                return NotFound();

            if (!_chataiModule.DeleteExploration(id, userId, DateTime.Now))
                return BadRequest("刪除探索紀錄失敗。");

            return Ok();
        }

        private static bool IsOwnedBy(Exploration? record, string accountName) =>
            record != null && !record.is_del && record.account_name == accountName;

        private static ExplorationResponse ToResponse(Exploration record) => new()
        {
            Id = record.id,
            Topic = record.topic,
            TopicCustomLabel = record.topic_custom_label,
            Status = record.status,
            History = ParseJsonOrNull(record.history_json),
            Answers = ParseJsonOrNull(record.answers_json),
            Summary = ParseJsonOrNull(record.summary_json),
            Card = ParseJsonOrNull(record.card_json),
            Fast = ParseJsonOrNull(record.fast_json),
            CreatedAt = record.create_date,
            UpdatedAt = record.update_date,
        };

        private static JsonElement? ParseJsonOrNull(string? json)
        {
            if (string.IsNullOrWhiteSpace(json)) return null;
            return JsonSerializer.Deserialize<JsonElement>(json);
        }
    }
}

