import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen, waitFor, within } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { renderApp } from '../helpers/renderApp'

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

/**
 * 一律透過 i18n key 取文字，而非寫死中文字面值，
 * 這樣調整文案時不會連帶弄壞這支測試。
 */
const label = (key: string) => i18n.global.t(key)

/**
 * exploration 現在是後端持久化的資源（見 ExplorationController / RunController.
 * RunAdvisingExploreFlow），這裡用一個記憶體內的 Map 模擬那個後端：explorationApi.ts 負責
 * CRUD（answers/summary/card/fast/status），advisingApi.ts 的 sendAdvisingMessage 負責
 * 「呼叫 AI + 把這輪對話 append 回 history」，跟真實後端的職責切分一致。
 */
const { store } = vi.hoisted(() => {
  interface StoredExploration {
    id: string
    topic: string
    topicCustomLabel?: string
    status: string
    history: { role: string; text: string }[]
    answers: unknown[]
    summary?: unknown
    card?: unknown
    fast?: unknown
    createdAt: string
    updatedAt: string
  }
  return { store: new Map<string, StoredExploration>() }
})

vi.mock('@/services/explorationApi', () => ({
  createExploration: vi.fn(async (input: { topic: string; topicCustomLabel?: string }) => {
    const now = new Date().toISOString()
    const record = {
      id: `exp-${store.size + 1}`,
      topic: input.topic,
      topicCustomLabel: input.topicCustomLabel,
