      await waitFor(
        () => expect(screen.getByRole('button', { name: label('card.bookAppointment') })).toBeInTheDocument(),
        { timeout: 12000 }
      )
      expect(screen.getAllByRole('img', { name: label('card.title') }).length).toBeGreaterThan(0)
    },
    40000
  )
})

