import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen, waitFor } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { STORAGE_KEYS } from '@/storage/keys'
import { renderApp } from '../helpers/renderApp'

const label = (key: string) => i18n.global.t(key)

const redirectToLogin = vi.fn()

/**
 * ConsentPage 的「進入下一步」用 requireAuth()（見 src/services/auth.ts）檢查登入態，
 * redirectToLogin() 實際上會改 window.location.href，jsdom 環境下沒必要真的跑那段，
 * 這裡只驗證「有沒有被呼叫」、以及呼叫後有沒有正確擋下原本要做的頁面跳轉。
 */
vi.mock('@/services/auth', async () => {
  const actual = await vi.importActual<typeof import('@/services/auth')>('@/services/auth')
  return { ...actual, redirectToLogin }
})

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((query: string) => ({
      matches: false,
      media: query,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('consent page auth guard', () => {
  beforeEach(() => {
    localStorage.clear()
    redirectToLogin.mockClear()
    stubMatchMedia()
  })

  it('redirects to login instead of continuing when there is no token', async () => {
    const user = userEvent.setup()
    await renderApp('/consent')

    await user.click(await screen.findByRole('checkbox'))
    await user.click(screen.getByRole('button', { name: label('consent.next') }))

    await waitFor(() => expect(redirectToLogin).toHaveBeenCalledTimes(1))
    expect(screen.queryByRole('button', { name: label('ritual.continue') })).not.toBeInTheDocument()
  })

  it('continues to the ritual page when a token is present', async () => {
    localStorage.setItem(STORAGE_KEYS.jwtToken, 'test-token')
    const user = userEvent.setup()
    await renderApp('/consent')

    await user.click(await screen.findByRole('checkbox'))
    await user.click(screen.getByRole('button', { name: label('consent.next') }))

    expect(await screen.findByRole('button', { name: label('ritual.continue') })).toBeInTheDocument()
    expect(redirectToLogin).not.toHaveBeenCalled()
  })
})

