        /// </summary>
        [HttpGet]
        public IActionResult Login(string? returnUrl)
        {
#if DEBUG
            return LocalhostLoginReturnToten(returnUrl);

#endif

            if (!(AuthorizeManagement.CurrentUser?.Identity?.IsAuthenticated ?? false))
            {
                var callbackUrl = $"{_appSettingConfig.BaseUrl}saml2-callback";
                // returnUrl 要跟著 SAML 這趟外部導轉的來回一起保留下來，最簡單可靠的方式就是把它
