﻿using chatai.Core.Config;
using chatai_backend.Controllers.Base;
using chatai_backend.Helpers;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Authorization;
using ntu.Sso.Service;

namespace chatai_backend.Controllers
{
    [Route("[action]")]
    [AllowAnonymous]
    public class HomeController : BaseController
    {
        private readonly ILogger<HomeController> _logger;
        private readonly AppSettingConfig _appSettingConfig;

        private readonly ISaml2Service _saml2;

        public HomeController(ILogger<HomeController> logger, AppSettingConfig appSettingConfig, ISaml2Service saml2Service)
        {
            _logger = logger;
            _appSettingConfig = appSettingConfig;

            _saml2 = saml2Service;
        }

        [HttpGet]
        public IActionResult Login()
        {
#if DEBUG
            return LocalhostLoginReturnToten();

#endif

            if (!(AuthorizeManagement.CurrentUser?.Identity?.IsAuthenticated ?? false))
                return _saml2.InitiateLogin($"{_appSettingConfig.BaseUrl}saml2-callback");

            return LoginReturnToten();
        }

        /// <summary>
        /// sso 2.0
        /// </summary>
        /// <param name="returnUrl"></param>
        /// <returns></returns>
        [HttpGet]
        public async Task<IActionResult> Saml2CallbackAsync()
        {
            if (!(AuthorizeManagement.CurrentUser.Identity?.IsAuthenticated ?? false))
                return this.Redirect(_appSettingConfig.FrontUrl);

            return LoginReturnToten();
        }

        [HttpGet]
        public IActionResult GetUser()
        {
            var identitiesInfo = AuthorizeManagement.CurrentUser.Identities
               .Select(identity =>
               {
                   var authType = identity.AuthenticationType ?? "None";
                   var claims = string.Join(Environment.NewLine, identity.Claims.Select(c => $"  {c.Type}: {c.Value}"));
                   return $"AuthenticationType: {authType}{Environment.NewLine}Claims:{Environment.NewLine}{claims}";
               });

            var allIdentitiesInfo = string.Join($"{Environment.NewLine}{Environment.NewLine}", identitiesInfo);

            return this.Content(allIdentitiesInfo);
        }


        [HttpGet]
        public async Task<IActionResult> LogoutAsync()
        {
            await HttpContext.SignOutAsync(CookieAuthenticationDefaults.AuthenticationScheme);

            return this.Redirect($"https://portal.aca.ntu.edu.tw/sso-gateway/logout?url={Uri.EscapeDataString(_appSettingConfig.FrontUrl)}");
        }

        private IActionResult LoginReturnToten()
        {
            (string token, DateTime loginDate, DateTime expDate) = JWTHelper.GenerateToken(AuthorizeManagement.CurrentUser.AccountName, AuthorizeManagement.CurrentUser.ChineseName, AuthorizeManagement.CurrentUser.AccountTypeCode);

            return this.Redirect($"{_appSettingConfig.FrontUrl}/login?token={token}");
        }

        /// <summary>
        /// 本機測試：模擬一個已登入的使用者
        /// </summary>
        /// <returns></returns>
        private IActionResult LocalhostLoginReturnToten()
        {
            (string token, DateTime loginDate, DateTime expDate) = JWTHelper.GenerateToken("waynechen", "陳亭瑋", "s");

            return this.Redirect($"{_appSettingConfig.FrontUrl}/login?token={token}");
        }
    }
}

