/// <summary>
/// 決定登入完要導去哪裡。returnUrl 是使用者可控的輸入，只接受同源相對路徑
/// （Url.IsLocalUrl 擋掉絕對網址、//host 這類 protocol-relative 網址），避免被利用做
/// 開放重導向（open redirect）；沒帶或不合法一律退回原本導去主站 /login 的行為。
/// 不管驗證結果如何，最終網址永遠是自己信任的 FrontUrl 組出來的，不會直接redirect使用者輸入。
/// </summary>
private string ResolveReturnUrl(string? returnUrl)
{
    var front = _appSettingConfig.FrontUrl.TrimEnd('/');
    if (string.IsNullOrWhiteSpace(returnUrl) || !Url.IsLocalUrl(returnUrl))
        return $"{front}/login";

    return $"{front}{returnUrl}";
}

