import { persistRenewedToken, readAuthToken } from './auth'
import { getApiUrl } from './advisingApi'
import type {
  Answer,
  ConversationTurn,
  Exploration,
  ExplorationStatus,
  FastAssessment,
  SelfAwarenessCard,
  SummarySection,
  TopicKey
} from '@/types'

export class ExplorationApiError extends Error {
  status?: number

  constructor(message: string, status?: number) {
    super(message)
    this.status = status
  }
}

/** 對應後端 ExplorationController 的 ExplorationResponse（camelCase JSON，見 chatai_backend 的 JsonOptions 預設）。 */
interface ExplorationDto {
  id: string
  topic: TopicKey
  topicCustomLabel?: string | null
  status: ExplorationStatus
  history?: ConversationTurn[] | null
  answers?: Answer[] | null
  summary?: SummarySection[] | null
  card?: SelfAwarenessCard | null
  fast?: FastAssessment | null
  createdAt: string
  updatedAt: string
}

function toExploration(dto: ExplorationDto): Exploration {
  return {
    id: dto.id,
    topic: dto.topic,
    topicCustomLabel: dto.topicCustomLabel ?? undefined,
    answers: dto.answers ?? [],
    summary: dto.summary ?? undefined,
    card: dto.card ?? undefined,
    status: dto.status,
    createdAt: dto.createdAt,
    updatedAt: dto.updatedAt,
    history: dto.history ?? [],
    fast: dto.fast ?? undefined
  }
}

async function authorizedFetch(path: string, init: RequestInit = {}): Promise<Response> {
  const token = readAuthToken()
  if (!token) throw new ExplorationApiError('缺少登入憑證')

  const res = await fetch(getApiUrl(path), {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      'X-Access-Token': `Bearer ${token}`,
      ...(init.headers ?? {})
    }
  })

  persistRenewedToken(res)

  if (!res.ok) {
    const errorText = await res.text().catch(() => '')
    throw new ExplorationApiError(errorText || `探索紀錄 API 請求失敗 (${res.status})`, res.status)
  }

  return res
}

export async function listExplorations(): Promise<Exploration[]> {
  const res = await authorizedFetch('/api/explorations')
  const dtos = (await res.json()) as ExplorationDto[]
  return dtos.map(toExploration).sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
}

export async function findInProgress(): Promise<Exploration | null> {
  const all = await listExplorations()
  return all.find(r => r.status === 'in-progress') ?? null
}

/** 找不到，或這筆紀錄不屬於目前登入的使用者（後端一律回 404，不區分兩者）時回傳 null。 */
export async function getExploration(id: string): Promise<Exploration | null> {
  try {
    const res = await authorizedFetch(`/api/explorations/${id}`)
    return toExploration((await res.json()) as ExplorationDto)
  } catch (err) {
    if (err instanceof ExplorationApiError && err.status === 404) return null
    throw err
  }
}

export async function createExploration(input: { topic: TopicKey; topicCustomLabel?: string }): Promise<Exploration> {
  const res = await authorizedFetch('/api/explorations', {
    method: 'POST',
    body: JSON.stringify({ topic: input.topic, topicCustomLabel: input.topicCustomLabel })
  })
  return toExploration((await res.json()) as ExplorationDto)
}

/**
 * 更新 answers/summary/card/fast/status 這幾個前端解析出來的衍生欄位；history（AI 對話的權威狀態）
 * 不在這裡動，由 RunController.RunAdvisingExploreFlow 在每輪對話結束後直接存回去。
 */
export async function updateExplorationDerived(
  id: string,
  patch: {
    answers?: Answer[]
    summary?: SummarySection[]
    card?: SelfAwarenessCard
    fast?: FastAssessment
    status?: ExplorationStatus
  }
): Promise<void> {
  await authorizedFetch(`/api/explorations/${id}`, {
    method: 'PATCH',
    body: JSON.stringify(patch)
  })
}

export async function deleteExploration(id: string): Promise<void> {
  await authorizedFetch(`/api/explorations/${id}`, { method: 'DELETE' })
}

import { STORAGE_KEYS } from '@/storage/keys'

const DEFAULT_MODEL = 'claude'

/**
 * 從 _frontend/chatai 整頁導過來時，網址帶著 ?token=<jwt>（同源時其實不需要，是跨源部署時的保險）、
 * 選擇性帶 ?model=<gemini|openai|claude>（對應原本 ?flow=7&model=... 的模型切換能力）。
 * 讀出來寫進 localStorage 後就把這兩個參數從網址上拿掉，避免留在瀏覽紀錄或分享出去的連結裡。
 */
export function consumeIncomingParams(): void {
  const params = new URLSearchParams(window.location.search)
  const token = params.get('token')
  const model = params.get('model')
  if (!token && !model) return

  try {
    if (token) localStorage.setItem(STORAGE_KEYS.jwtToken, token)
    if (model) localStorage.setItem(STORAGE_KEYS.model, model)
  } catch {
    // localStorage unavailable（配額用完、隱私模式）— readAuthToken()/readModelPreference() 會拿不到值
  }

  params.delete('token')
  params.delete('model')
  const query = params.toString()
  const url = `${window.location.pathname}${query ? `?${query}` : ''}${window.location.hash}`
  window.history.replaceState(null, '', url)
}

export function readAuthToken(): string | null {
  try {
    return localStorage.getItem(STORAGE_KEYS.jwtToken)
  } catch {
    return null
  }
}

/**
 * 後端在 token 過半效期時會用 X-Access-Token-Renewed response header 換發一顆新的（見
 * chatai_backend Program.cs 的 sliding renewal middleware）。有帶就存回 localStorage，
 * 讓 readAuthToken() 下次讀到的是新 token，藉此讓持續活躍的 session 不會撞到 8 小時上限。
 */
export function persistRenewedToken(res: Response): void {
  const renewed = res.headers.get('X-Access-Token-Renewed')
  if (!renewed) return

  try {
    localStorage.setItem(STORAGE_KEYS.jwtToken, renewed)
  } catch {
    // localStorage unavailable — 忽略，下次還是會用舊 token 直到真的過期
  }
}

/** flow=7 底層要用哪個 AI 供應商呼叫 AdvisingChatService；沒特別指定時預設 claude（不是後端原本的 gemini）。 */
export function readModelPreference(): string {
  try {
    return localStorage.getItem(STORAGE_KEYS.model) || DEFAULT_MODEL
  } catch {
    return DEFAULT_MODEL
  }
}

/** 沒有登入態時導回主聊天站的登入頁；VITE_LOGIN_URL 未設定時什麼都不做（避免開發環境誤跳轉）。 */
export function redirectToLogin(): void {
  const loginUrl = import.meta.env.VITE_LOGIN_URL as string | undefined
  if (loginUrl) window.location.href = loginUrl
}

/**
 * 給流程關鍵按鈕（例如 ConsentPage 的「進入下一步」）在觸發動作前呼叫：main.ts 只在應用程式
 * 剛掛載那一刻檢查過一次 token，使用者停在某一頁太久、或 SSO session 在另一個分頁被登出，
 * 都可能讓 token 在那之後失效，之後的頁面卻不會再重新檢查。回傳 false 時呼叫端要中止原本的
 * 動作（已經導去登入頁了）。
 */
export function requireAuth(): boolean {
  if (readAuthToken()) return true
  redirectToLogin()
  return false
}

