import type { Exploration, TopicKey } from '@/types'
import { STORAGE_KEYS } from './keys'

interface CreateInput {
  topic: TopicKey
  topicCustomLabel?: string
}

function readAll(): Exploration[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEYS.explorations)
    if (!raw) return []
    return JSON.parse(raw) as Exploration[]
  } catch {
    return []
  }
}

function writeAll(list: Exploration[]): void {
  try {
    localStorage.setItem(STORAGE_KEYS.explorations, JSON.stringify(list))
  } catch {
    // localStorage unavailable (quota exceeded, private mode) — fail silently for this demo
  }
}

function generateId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) {
    return crypto.randomUUID()
  }
  return `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`
}

export function listExplorations(): Exploration[] {
  const all = readAll()
  return [...all].sort((a, b) =>
    new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime()
  )
}

export function getExploration(id: string): Exploration | null {
  return readAll().find(r => r.id === id) ?? null
}

export function createExploration(input: CreateInput): Exploration {
  const now = new Date().toISOString()
  const record: Exploration = {
    id: generateId(),
    topic: input.topic,
    topicCustomLabel: input.topicCustomLabel,
    answers: [],
    status: 'in-progress',
    createdAt: now,
    updatedAt: now
  }
  writeAll([...readAll(), record])
  return record
}

export function updateExploration(
  id: string,
  patch: Partial<Omit<Exploration, 'id' | 'createdAt'>>
): Exploration {
  const all = readAll()
  const idx = all.findIndex(r => r.id === id)
  if (idx < 0) throw new Error(`exploration ${id} not found`)
  const updated: Exploration = {
    ...all[idx],
    ...patch,
    // 呼叫端可明確指定 updatedAt（Demo 資料需要回填較早的時間），否則一律更新為現在
    updatedAt: patch.updatedAt ?? new Date().toISOString()
  }
  all[idx] = updated
  writeAll(all)
  return updated
}

export function findInProgress(): Exploration | null {
  return listExplorations().find(r => r.status === 'in-progress') ?? null
}

export function deleteExploration(id: string): void {
  writeAll(readAll().filter(r => r.id !== id))
}

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import { createExploration, updateExploration } from '@/storage/explorations'
import { renderApp } from '../helpers/renderApp'

/**
 * ExplorationPage 現在透過 @/services/explorationApi 打後端 API 讀寫探索紀錄，這裡用
 * 「委派給真正的 @/storage/explorations（localStorage）」的方式模擬後端，這樣上面這行
 * 準備測試資料用的 createExploration/updateExploration 寫法不用改。
 */
vi.mock('@/services/explorationApi', async () => {
  const storage = await vi.importActual<typeof import('@/storage/explorations')>('@/storage/explorations')
  return {
    createExploration: vi.fn(async (input: Parameters<typeof storage.createExploration>[0]) => storage.createExploration(input)),
    getExploration: vi.fn(async (id: string) => storage.getExploration(id)),
    listExplorations: vi.fn(async () => storage.listExplorations()),
    findInProgress: vi.fn(async () => storage.findInProgress()),
    updateExplorationDerived: vi.fn(async (id: string, patch: Record<string, unknown>) => {
      storage.updateExploration(id, patch)
    }),
    deleteExploration: vi.fn(async (id: string) => {
      storage.deleteExploration(id)
    })
  }
})

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('resume exploration progress without ?q=', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('lands on the furthest question with real data instead of resetting to question 1', async () => {
    // 模擬真實對話已經進行到第 3 題（前兩題已作答、第 3 題的題目資料已經到了但還沒作答），
    // 這正是重新整理頁面時 exploration.answers/history 會長的樣子。
    const record = createExploration({ topic: 'career' })
    updateExploration(record.id, {
      answers: [
        { questionIndex: 0, text: '修課負擔', updatedAt: new Date().toISOString(), question: 'Q1?', reflection: 'R1' },
        { questionIndex: 1, text: '成績不好壓力大', updatedAt: new Date().toISOString(), question: 'Q2?', reflection: 'R2' },
        { questionIndex: 2, text: '', updatedAt: new Date().toISOString(), question: 'Q3?', reflection: 'R3' }
      ],
      history: [
        { role: 'user', text: 'start' },
        { role: 'model', text: 'opening' },
        { role: 'user', text: '課業學習' },
        { role: 'model', text: 'fast prompt' },
        { role: 'user', text: '5,4,5,4,6,4' },
        { role: 'model', text: 'Q1?' },
        { role: 'user', text: '修課負擔' },
        { role: 'model', text: 'Q2?' },
        { role: 'user', text: '成績不好壓力大' },
        { role: 'model', text: 'Q3?' }
      ]
    })

    // 不帶 ?q=，模擬重新整理頁面／瀏覽器前進後退
    await renderApp(`/journey/${record.id}`)

    expect(await screen.findByText('03')).toBeInTheDocument()
    expect(screen.queryByText('01')).not.toBeInTheDocument()
  })
})

