    }))
  })
}

describe('home page resume draft', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('does not offer to resume an old abandoned draft once a later exploration was completed', async () => {
    // 很久以前中途放棄的舊探索（時間管理，還停在第 1 題）
    const stale = createExploration({ topic: 'time-management' })
    updateExploration(stale.id, { updatedAt: '2026-01-01T00:00:00.000Z' })

    // 之後又完整走完了另一個議題（生涯探索）
