    updateExploration(completed.id, { status: 'completed', updatedAt: '2026-01-01T00:00:00.000Z' })

    const current = createExploration({ topic: 'time-management' })
    updateExploration(current.id, { updatedAt: '2026-09-01T00:00:00.000Z' })

    await renderApp('/home')

    expect(await screen.findByRole('button', { name: /未完成續填/ })).toBeInTheDocument()
  })
})

