}

.beamInner {
  position: relative;
  border-radius: 12.5px;
  background: #232326;
}

@keyframes spin {
  to {
    transform: rotate(1turn);
  }
}

.primary.disabled {
  background: var(--surface-hover-strong);
  color: var(--color-fg-hushed);
  box-shadow: none;
}

.secondary.disabled,
.outline.disabled,
.text.disabled,
.link.disabled,
.quiet.disabled,
.danger.disabled {
  opacity: 0.45;
}

