import { describe, it, expect } from 'vitest'
import { render, screen } from '@testing-library/vue'
import Button from '@/components/ui/Button.vue'
import styles from '@/components/ui/Button.module.css'

describe('Button loading state', () => {
  it('renders a plain button with no beam wrapper when not loading', () => {
    render(Button, { slots: { default: '送出' } })
    const button = screen.getByRole('button', { name: '送出' })
    expect(button.parentElement?.className.includes(styles.beam)).toBe(false)
  })

  it('wraps the button in the beam/beamInner rotating-ring structure when loading', () => {
    render(Button, { props: { loading: true }, slots: { default: '送出' } })
    const button = screen.getByRole('button', { name: '送出' })
    const beamInner = button.parentElement
    const beam = beamInner?.parentElement
    expect(beamInner?.className).toContain(styles.beamInner)
    expect(beam?.className).toContain(styles.beam)
  })

  it('keeps caller-provided classes on the actual button in both states', () => {
    const { rerender } = render(Button, {
      props: { class: 'custom-class' },
      slots: { default: '送出' }
    })
    expect(screen.getByRole('button', { name: '送出' }).className).toContain('custom-class')

    rerender({ class: 'custom-class', loading: true })
    expect(screen.getByRole('button', { name: '送出' }).className).toContain('custom-class')
  })
})

