    await user.click(nextButton)

    // 送出後：骨架出現，原本的題目/送出按鈕都從畫面上消失（不是被蓋住，是整段被換掉）
    expect(await screen.findByText(i18n.global.t('exploration.thinking'))).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: i18n.global.t('exploration.next') })).not.toBeInTheDocument()

    resolveSend('（第 6 / 10 題）\n\n很棒的答案。\n\n那接下來呢？')

    await waitFor(() => expect(screen.queryByText(i18n.global.t('exploration.thinking'))).not.toBeInTheDocument())
  })
})

