async function advance() {
  if (sending.value) return
  try {
    const { isFinal } = await send(draft.value)
    if (isFinal) {
      if (exploration.value) router.push(`/settle/${exploration.value.id}`)
      return
    }
    if (currentIndex.value >= TOTAL - 1) {
      // 已經是最後一題，這輪回覆卻不是總結報告格式（例如探索已結束後又送出訊息被 AI 婉拒，
      // 見 AdvisingChatService.cs Stage 3 的「輸出總結報告後」規則）——不能再往不存在的第 11
      // 題推進，留在原地並提示錯誤，畫面題號才不會超出 TOTAL。
      showToast(t('exploration.finishError'))
      return
    }
    currentIndex.value += 1
    activeIndex.value = currentIndex.value
    phase.value = 'reflection'
  } catch (err) {
    console.error('[ExplorationPage] advance failed', err)
    showToast(isQuotaError(err) ? t('common.quotaError') : t('exploration.sendError'))
  }
}

// 瀏覽（非送出）題目：夾在 0 ~ 目前進度之間，超過目前進度的題目還沒作答，不能瀏覽
function viewQuestion(index: number) {
  currentIndex.value = Math.max(0, Math.min(activeIndex.value, index))
  phase.value = 'question'
}

