public static List<(string Role, string Text)> Parse(string? json)
{
    if (string.IsNullOrWhiteSpace(json))
        return new List<(string Role, string Text)>();

    var turns = JsonSerializer.Deserialize<List<Turn>>(json) ?? new List<Turn>();
    // Claude/Gemini 的多輪對話 API 都不接受空白內容的訊息；history 裡只要混進一筆空白
    // 訊息（例如曾經允許送出空白答案，見 RunController.cs 的 input_value 驗證），這筆
    // 探索之後每輪都要重送整段 history，會永久卡在同一個 400 錯誤。讀取時直接濾掉這種
    // 壞資料，讓已經中招的舊紀錄也能自動復原，不用另外寫一次性的資料修復腳本。
    return turns
        .Where(t => !string.IsNullOrWhiteSpace(t.role) && !string.IsNullOrWhiteSpace(t.text))
        .Select(t => (t.role, t.text))
        .ToList();
}

