import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { seedDemoExploration } from '@/data/demo-seed'
import { renderApp } from '../helpers/renderApp'

/**
 * ExplorationPage 現在透過 @/services/explorationApi 打後端 API 讀寫探索紀錄，這裡用
 * 「委派給真正的 @/storage/explorations（localStorage）」的方式模擬後端，這樣上面這行
 * 準備測試資料用的 seedDemoExploration 寫法不用改。
 */
vi.mock('@/services/explorationApi', async () => {
  const storage = await vi.importActual<typeof import('@/storage/explorations')>('@/storage/explorations')
  return {
    createExploration: vi.fn(async (input: Parameters<typeof storage.createExploration>[0]) => storage.createExploration(input)),
    getExploration: vi.fn(async (id: string) => storage.getExploration(id)),
    listExplorations: vi.fn(async () => storage.listExplorations()),
    findInProgress: vi.fn(async () => storage.findInProgress()),
    updateExplorationDerived: vi.fn(async (id: string, patch: Record<string, unknown>) => {
      storage.updateExploration(id, patch)
    }),
    deleteExploration: vi.fn(async (id: string) => {
      storage.deleteExploration(id)
    })
  }
})

/**
 * 空白答案一旦送到後端，成功後會被原封不動存進 history_json，Claude/Gemini 的多輪對話 API
 * 都不接受空字串內容，之後這筆探索每輪都要重送整段 history，會永久卡死（見 RunController.cs
 * 的說明）。這裡直接斷言 sendAdvisingMessage 完全沒被呼叫，確保這個防呆是從一開始就擋下來，
 * 不是等後端拒絕才處理。
 */
const sendAdvisingMessage = vi.fn()
vi.mock('@/services/advisingApi', () => ({
  AdvisingApiError: class AdvisingApiError extends Error {},
  isQuotaError: () => false,
  sendAdvisingMessage
}))

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('exploration blank answer guard', () => {
  beforeEach(() => {
    localStorage.clear()
    sendAdvisingMessage.mockClear()
    stubMatchMedia()
  })

  it('disables the next button and does not call the API when the answer is blank', async () => {
    const user = userEvent.setup()
    const exp = seedDemoExploration('midway') // 前 5 題已作答，落地在第 5 題，textarea 預填範例答案
    await renderApp(`/journey/${exp.id}`)

    const nextButton = await screen.findByRole('button', { name: i18n.global.t('exploration.next') })
    expect(nextButton).not.toBeDisabled()

    const textarea = screen.getByRole('textbox', { name: i18n.global.t('exploration.inputLabel') })
    await user.clear(textarea)

    expect(nextButton).toBeDisabled()

    await user.click(nextButton)
    expect(sendAdvisingMessage).not.toHaveBeenCalled()
  })
})

