using chatai.Core.Helper;
using chatai_backend.Attribute;
using chatai_backend.Helpers;
using chatai_backend.Model;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc.Filters;
using ntu.Common.Utility.Exception;
using ntu.Common.Utility.Extension;
using System.Security.Authentication;

namespace chatai_backend.Filter;

//[AttributeUsage(AttributeTargets.Method | AttributeTargets.Class)]
public class ValidateJWTFilter : IActionFilter
{
    private readonly ILogger<ValidateJWTFilter> _logger;

    public ValidateJWTFilter(ILogger<ValidateJWTFilter> logger)
    {
        _logger = logger;
    }

    public void OnActionExecuting(ActionExecutingContext context)
    {

        if (IsAllowAnonymous(context)) return;

#if !DEBUG

        if (!IsNeedJWT(context)) return;

        if (!context.HttpContext.Request.Headers.TryGetValue("X-Access-Token", out var encryptedSignature))
            throw new CustomException("缺少 X-Access-Token Header.");

        var authToken = encryptedSignature.ToNullString();
        if (string.IsNullOrEmpty(authToken) || !authToken.StartsWith("Bearer"))
            throw new CustomException("Invalid X-Access-Token Header");

        // 驗證 Token 是否有效
        if (!JWTHelper.ValidateToken(authToken, out var principal))
            throw new AuthenticationException("X-Access-Token驗證失敗");

#endif

    }

    public void OnActionExecuted(ActionExecutedContext context)
    {
        // 無需處理
    }

    private static bool IsNeedJWT(ActionExecutingContext context)
    {
        return context.ActionDescriptor.EndpointMetadata
            .Any(em => em is NeedJWTAttribute);
    }

    private static bool IsAllowAnonymous(ActionExecutingContext context)
    {
        return context.ActionDescriptor.EndpointMetadata
            .Any(em => em is AllowAnonymousAttribute);
    }
}

