async function persistDerived(current: Exploration, patch: Partial<Exploration>): Promise<void> {
  try {
    await updateExplorationDerived(current.id, {
      answers: patch.answers ?? current.answers,
      summary: patch.summary ?? current.summary,
      card: patch.card ?? current.card,
      fast: patch.fast ?? current.fast,
      status: patch.status ?? current.status
    })
  } catch (err) {
    // 對話本身已經成功（AI 回覆已經拿到、本機狀態已經更新），衍生欄位存檔失敗不應該擋住
    // 使用者繼續往下走；下一次任何欄位變動（含 useExploration.ts 的自動存檔）都會再送一次。
    console.error('[useAdvisingConversation] persist derived fields failed', err)
  }
}

/** 送出一輪使用者訊息，回傳這輪 AI 的完整回覆（已經套用過 Stage 2/3 解析並寫回 exploration）。 */
async function send(userText: string): Promise<SendOutcome> {
  const current = exploration.value
  if (!current) throw new Error('exploration not loaded')

  sending.value = true
  streamingText.value = ''
  error.value = null

  try {
    const reply = await sendAdvisingMessage(current.id, userText, delta => {
      streamingText.value += delta
    })

    let patch: Partial<Exploration> = {}
    let isFinal = false

    const stage2 = parseStage2Reply(reply)
    if (stage2) {
      patch.answers = applyStage2Reply(current, stage2, reply)
    } else if (isFinalReport(reply)) {
      isFinal = true
      patch = { ...patch, ...applyFinalReport(current, reply) }
    } else if (!isFastAssessmentPrompt(reply) && (current.fast?.scores?.length ?? 0) > 0) {
      // 判斷「是否已進入 Stage 2」要用 fast.scores 是否存在，不能用 answers.length，否則
      // Stage 2 第一題（FAST 結束後緊接輸出的合併回覆）解析失敗時會被排除在保底機制外，畫面
      // 直接空白；且如果改成完全不判斷，Stage 1 開場白那輪也會被誤存成假的第一題。
      const fallbackAnswers = buildFallbackAnswers(current, reply)
      if (fallbackAnswers) patch.answers = fallbackAnswers
    }

    exploration.value = { ...current, ...patch, updatedAt: new Date().toISOString() }
    await persistDerived(current, patch)
    return { reply, isFinal }
  } catch (err) {
    error.value = err instanceof Error ? err.message : String(err)
    // 錯誤原因（後端回的 error 訊息、或 fetch/串流讀取本身的例外）留一份在 console，
    // 不然畫面只會顯示制式的「傳送失敗」，事後完全查不出當下實際發生什麼事。
    console.error('[useAdvisingConversation] send failed', err)
    throw err
  } finally {
    sending.value = false
  }
}

/**
 * 送出 Stage 1.5 的六題自評分數（後端期待的格式是 "4,5,3,2,4,3"）。
 * 分數本身先存起來；directionScore/resourceScore/quadrant/advice 等 Stage 3 報告解析出來才補上。
 */

import { ref, type Ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { Exploration } from '@/types'
import { sendAdvisingMessage } from '@/services/advisingApi'
import { updateExplorationDerived } from '@/services/explorationApi'
import {
  buildSelfAwarenessCard,
  isFinalReport,
  isFastAssessmentPrompt,
  parseStage2Reply,
  parseStage3Report
} from '@/services/advisingParser'
import { TOPICS } from '@/data/topics'
import { TOTAL_QUESTIONS } from '@/constants/exploration'

export interface SendOutcome {
  reply: string
  isFinal: boolean
}

/**
 * 驅動與 AdvisingChatService 的真實多輪對話：送出使用者這輪的回覆、串流累積 AI 回覆、
 * 依目前階段解析回覆內容並把衍生欄位（answers/summary/card/fast/status）PATCH 回後端。
 *
 * 對話紀錄本身（history）不在這裡送出或寫回——後端在 RunController.RunAdvisingExploreFlow
 * 收到 exploration_id 後會自己從資料表讀出歷史、呼叫 AI、串流結束後存回去。
 */
export function useAdvisingConversation(exploration: Ref<Exploration | null>) {
  const { t } = useI18n()
  const sending = ref(false)
  const streamingText = ref('')
  const error = ref<string | null>(null)

  function topicLabelOf(current: Exploration): string {
    return current.topicCustomLabel ?? t(TOPICS.find(o => o.key === current.topic)?.labelKey ?? current.topic)
  }

  /**
   * 非預期格式（不是新一題、不是總結報告、也不是 FAST 自評提示）——多半是 Stage 2 期間解析失敗，
   * 用原始文字頂著一個新題目卡位，至少不讓畫面開天窗。
   *
   * 但 10 題都已經有紀錄時不能再套用這個保底機制：AdvisingChatService.cs Stage 3 規定「輸出總結
   * 報告後，如果學生仍持續提出其他問題」要婉拒並提醒探索已完成，這種回覆同樣對不上 Stage 2／
   * Stage 3 格式，若還是無腦塞成新一題，會生出不存在的「第 11 題」，連帶讓首頁誤判續填題號
   * 跑掉（見 HomePage.vue draftQuestionNumber）。這種情況下回傳 undefined，answers 保持原樣。
   */
  function buildFallbackAnswers(current: Exploration, reply: string) {
    if (current.answers.length >= TOTAL_QUESTIONS) {
      console.warn(
        '[useAdvisingConversation] reply after all questions were answered did not match final report format, ignoring instead of fabricating an extra question',
        reply
      )
      return undefined
    }
    console.warn('[useAdvisingConversation] Stage 2 reply did not match expected format, using raw fallback', reply)
    const answers = [...current.answers]
    answers.push({
      questionIndex: answers.length,
      text: '',
      updatedAt: new Date().toISOString(),
      rawReply: reply
    })
    return answers
  }

  function applyStage2Reply(current: Exploration, stage2: NonNullable<ReturnType<typeof parseStage2Reply>>, reply: string) {
    const answers = [...current.answers]
    const idx = answers.findIndex(a => a.questionIndex === stage2.questionNumber - 1)
    const entry = {
      questionIndex: stage2.questionNumber - 1,
      text: answers[idx]?.text ?? '',
      updatedAt: new Date().toISOString(),
      reflection: stage2.reflection,
      question: stage2.question,
      rawReply: reply
    }
    if (idx >= 0) answers[idx] = { ...answers[idx], ...entry }
    else answers.push(entry)
    return answers
  }

  function applyFinalReport(current: Exploration, reply: string): Partial<Exploration> {
    const parsed = parseStage3Report(reply)
    const summary = parsed?.summary ?? [{ key: 'raw' as const, title: '總結報告', body: reply }]
    const topicLabel = topicLabelOf(current)
    const patch: Partial<Exploration> = {
      summary,
      card: {
        topicLabel,
        date: new Date().toISOString().slice(0, 10),
        ...buildSelfAwarenessCard(topicLabel, summary)
      },
      status: 'completed'
    }
    if (parsed?.fast && current.fast) patch.fast = { ...current.fast, ...parsed.fast }
    return patch
  }

  async function persistDerived(current: Exploration, patch: Partial<Exploration>): Promise<void> {
    try {
      await updateExplorationDerived(current.id, {
        answers: patch.answers ?? current.answers,
        summary: patch.summary ?? current.summary,
        card: patch.card ?? current.card,
        fast: patch.fast ?? current.fast,
        status: patch.status ?? current.status
      })
    } catch (err) {
      // 對話本身已經成功（AI 回覆已經拿到、本機狀態已經更新），衍生欄位存檔失敗不應該擋住
      // 使用者繼續往下走；下一次任何欄位變動（含 useExploration.ts 的自動存檔）都會再送一次。
      console.error('[useAdvisingConversation] persist derived fields failed', err)
    }
  }

  /** 送出一輪使用者訊息，回傳這輪 AI 的完整回覆（已經套用過 Stage 2/3 解析並寫回 exploration）。 */
  async function send(userText: string): Promise<SendOutcome> {
    const current = exploration.value
    if (!current) throw new Error('exploration not loaded')

    sending.value = true
    streamingText.value = ''
    error.value = null

    try {
      const reply = await sendAdvisingMessage(current.id, userText, delta => {
        streamingText.value += delta
      })

      let patch: Partial<Exploration> = {}
      let isFinal = false

      const stage2 = parseStage2Reply(reply)
      if (stage2) {
        patch.answers = applyStage2Reply(current, stage2, reply)
      } else if (isFinalReport(reply)) {
        isFinal = true
        patch = { ...patch, ...applyFinalReport(current, reply) }
      } else if (!isFastAssessmentPrompt(reply) && (current.fast?.scores?.length ?? 0) > 0) {
        // 判斷「是否已進入 Stage 2」要用 fast.scores 是否存在，不能用 answers.length，否則
        // Stage 2 第一題（FAST 結束後緊接輸出的合併回覆）解析失敗時會被排除在保底機制外，畫面
        // 直接空白；且如果改成完全不判斷，Stage 1 開場白那輪也會被誤存成假的第一題。
        const fallbackAnswers = buildFallbackAnswers(current, reply)
        if (fallbackAnswers) patch.answers = fallbackAnswers
      }

      exploration.value = { ...current, ...patch, updatedAt: new Date().toISOString() }
      await persistDerived(current, patch)
      return { reply, isFinal }
    } catch (err) {
      error.value = err instanceof Error ? err.message : String(err)
      // 錯誤原因（後端回的 error 訊息、或 fetch/串流讀取本身的例外）留一份在 console，
      // 不然畫面只會顯示制式的「傳送失敗」，事後完全查不出當下實際發生什麼事。
      console.error('[useAdvisingConversation] send failed', err)
      throw err
    } finally {
      sending.value = false
    }
  }

  /**
   * 送出 Stage 1.5 的六題自評分數（後端期待的格式是 "4,5,3,2,4,3"）。
   * 分數本身先存起來；directionScore/resourceScore/quadrant/advice 等 Stage 3 報告解析出來才補上。
   */
  async function submitFastScores(scores: number[]): Promise<SendOutcome> {
    const current = exploration.value
    if (!current) throw new Error('exploration not loaded')
    const fast = { scores }
    exploration.value = { ...current, fast, updatedAt: new Date().toISOString() }
    await persistDerived(current, { fast })
    return send(scores.join(','))
  }

  return { sending, streamingText, error, send, submitFastScores }
}

