async function advance() {
  // 空白答案不能送出：一旦送到後端會被原封不動存進 history_json，之後每輪都要重送整段
  // history 給 Claude，Claude 的 Messages API 不接受空字串的訊息內容，會讓這筆探索永久卡死
  // （見 RunController.cs 的說明）。按鈕本身的 disabled 已經擋過一次，這裡再擋一次防呆。
  if (sending.value || !draft.value.trim()) return
  try {
    const { isFinal } = await send(draft.value)
    if (isFinal) {
      if (exploration.value) router.push(`/settle/${exploration.value.id}`)
      return
    }
    if (currentIndex.value >= TOTAL - 1) {
      // 已經是最後一題，這輪回覆卻不是總結報告格式（例如探索已結束後又送出訊息被 AI 婉拒，
