import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { seedDemoExploration } from '@/data/demo-seed'
import { renderApp } from '../helpers/renderApp'

/**
 * ExplorationPage 現在透過 @/services/explorationApi 打後端 API 讀寫探索紀錄，這裡用
 * 「委派給真正的 @/storage/explorations（localStorage）」的方式模擬後端，這樣上面這行
 * 準備測試資料用的 seedDemoExploration 寫法不用改。updateExplorationDerived 特意模擬失敗，
 * 對應「總結報告拿到了、但存檔那次 PATCH 網路不穩失敗」的情境。
 */
vi.mock('@/services/explorationApi', async () => {
  const storage = await vi.importActual<typeof import('@/storage/explorations')>('@/storage/explorations')
  return {
    createExploration: vi.fn(async (input: Parameters<typeof storage.createExploration>[0]) => storage.createExploration(input)),
    getExploration: vi.fn(async (id: string) => storage.getExploration(id)),
    listExplorations: vi.fn(async () => storage.listExplorations()),
    findInProgress: vi.fn(async () => storage.findInProgress()),
    updateExplorationDerived: vi.fn(async () => {
      throw new Error('network blip')
    }),
    deleteExploration: vi.fn(async (id: string) => {
      storage.deleteExploration(id)
    })
  }
})

vi.mock('@/services/advisingApi', () => ({
  AdvisingApiError: class AdvisingApiError extends Error {},
  isQuotaError: () => false,
  sendAdvisingMessage: vi.fn(
    async () => '📋 你的學習規劃報告\n\n【你想談的議題】\n測試用議題\n\n🎓 推薦臺大學習資源\n（測試用，無相關資源）'
  )
}))

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('exploration final save failure', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('shows a specific error and stays on the page instead of navigating to a broken summary', async () => {
    const user = userEvent.setup()
    const exp = seedDemoExploration('answered') // 十題皆已作答，落地在第 10 題
    const { router } = await renderApp(`/journey/${exp.id}`)

    const finishButton = await screen.findByRole('button', { name: i18n.global.t('exploration.finish') })
    await user.click(finishButton)

    expect(await screen.findByText(i18n.global.t('exploration.finalSaveError'))).toBeInTheDocument()
    expect(router.currentRoute.value.path).toBe(`/journey/${exp.id}`)
  })
})

