const { t } = useI18n()
const { reduceMotion, settings } = useSettings()
const { showToast } = useToast()
const route = useRoute()
const router = useRouter()

const id = computed(() => route.params.id as string)
const { exploration, loading, setAnswer } = provideExploration(id)
const { send, sending, retryPersist } = useAdvisingConversation(exploration)

// 總結報告已經拿到、但存檔那次 PATCH 失敗時設成 true：下一次「完成探索」要走純重試存檔
// （retryPersist），不能再走 advance() 整段重送給 AI（見 advance() 內的說明）。
const finalSaveFailed = ref(false)

/**
 * 沒有帶 ?q= 時（例如重新整理頁面、瀏覽器前進/後退），不能直接假設是「全新進入第 1 題」——
 * exploration.answers 才是真正的進度來源，history 也是照這個進度往下送，兩者一定要對齊，
 * 否則畫面顯示第 1 題、但送出去的 history 其實已經是後面題目的內容（曾經真的發生過）。
 */
function maxAnsweredIndex(): number {
  const answers = exploration.value?.answers ?? []
  return answers.reduce((max, a) => Math.max(max, a.questionIndex), -1)
}

function initialIndex(): number {
  const requested = requestedQuestionNumber(route.query.q)
  if (Number.isFinite(requested) && requested >= 1) return Math.min(TOTAL, Math.trunc(requested)) - 1
  return Math.max(0, Math.min(TOTAL - 1, maxAnsweredIndex()))
}
function initialPhase(): Phase {
  const requested = requestedQuestionNumber(route.query.q)
  if (Number.isFinite(requested) && requested >= 1) return 'question'
  // 還沒有任何題目資料，或還停在第 1 題：走原本的反映段開場動畫。
  // 已經推進到第 1 題之後才重新整理：直接回到提問段，不要重播已經看過的反映文字。
  return maxAnsweredIndex() > 0 ? 'question' : 'reflection'
}

const currentIndex = ref(initialIndex())
// 目前實際問答進度的前緣題號；點進度點跳去看較早的題目時，currentIndex 會往回移動瀏覽，
// activeIndex 維持不動，用來判斷該題是否已經送出（不可再編輯）。
const activeIndex = ref(initialIndex())
const phase = ref<Phase>(initialPhase())
const draft = ref('')
const hintOpen = ref(false)

// 切換到不同探索（或同一路由帶不同 ?q）時，重新從查詢字串推算起始題號與階段
watch(
  () => `${route.params.id}:${route.query.q ?? ''}`,
  () => {
    currentIndex.value = initialIndex()
    activeIndex.value = currentIndex.value
    phase.value = initialPhase()
  }
)

// exploration 現在是非同步從後端載入（見 useExploration.ts），掛載當下 exploration.value 還是
// null，上面兩個 ref 的初始值只能先用「查無進度」推算。等 loading 轉為 false、真正的
// answers/history 進來後，要再算一次，不然重新整理頁面時畫面會卡在第 1 題，跟後端實際進度對不上。
watch(loading, isLoading => {

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { screen } from '@testing-library/vue'
import userEvent from '@testing-library/user-event'
import { i18n } from '@/i18n'
import { seedDemoExploration } from '@/data/demo-seed'
import { renderApp } from '../helpers/renderApp'

/**
 * ExplorationPage 現在透過 @/services/explorationApi 打後端 API 讀寫探索紀錄，這裡用
 * 「委派給真正的 @/storage/explorations（localStorage）」的方式模擬後端，這樣上面這行
 * 準備測試資料用的 seedDemoExploration 寫法不用改。updateExplorationDerived 特意模擬失敗，
 * 對應「總結報告拿到了、但存檔那次 PATCH 網路不穩失敗」的情境。
 */
vi.mock('@/services/explorationApi', async () => {
  const storage = await vi.importActual<typeof import('@/storage/explorations')>('@/storage/explorations')
  return {
    createExploration: vi.fn(async (input: Parameters<typeof storage.createExploration>[0]) => storage.createExploration(input)),
    getExploration: vi.fn(async (id: string) => storage.getExploration(id)),
    listExplorations: vi.fn(async () => storage.listExplorations()),
    findInProgress: vi.fn(async () => storage.findInProgress()),
    updateExplorationDerived: vi.fn(async () => {
      throw new Error('network blip')
    }),
    deleteExploration: vi.fn(async (id: string) => {
      storage.deleteExploration(id)
    })
  }
})

vi.mock('@/services/advisingApi', () => ({
  AdvisingApiError: class AdvisingApiError extends Error {},
  isQuotaError: () => false,
  sendAdvisingMessage: vi.fn(
    async () => '📋 你的學習規劃報告\n\n【你想談的議題】\n測試用議題\n\n🎓 推薦臺大學習資源\n（測試用，無相關資源）'
  )
}))

function stubMatchMedia() {
  Object.defineProperty(window, 'matchMedia', {
    writable: true,
    configurable: true,
    value: vi.fn().mockImplementation((q: string) => ({
      matches: false,
      media: q,
      onchange: null,
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      addListener: vi.fn(),
      removeListener: vi.fn(),
      dispatchEvent: vi.fn()
    }))
  })
}

describe('exploration final save failure', () => {
  beforeEach(() => {
    localStorage.clear()
    stubMatchMedia()
  })

  it('shows a specific error and stays on the page instead of navigating to a broken summary', async () => {
    const user = userEvent.setup()
    const exp = seedDemoExploration('answered') // 十題皆已作答，落地在第 10 題
    const { router } = await renderApp(`/journey/${exp.id}`)

    const finishButton = await screen.findByRole('button', { name: i18n.global.t('exploration.finish') })
    await user.click(finishButton)

    expect(await screen.findByText(i18n.global.t('exploration.finalSaveError'))).toBeInTheDocument()
    expect(router.currentRoute.value.path).toBe(`/journey/${exp.id}`)
  })
})

